function captionGen(keyword, platform, tone, rng){
  keyword=String(keyword||'').trim(); if(!keyword) return {error:'请填写主题关键词'};
  rng=rng||Math.random; platform=platform||'通用'; tone=tone||'日常';
  var tpl={
    'instagram':{'日常':[keyword+' 的一天，刚刚好 ✨','把 '+keyword+' 过成喜欢的样子 🌿','今日 '+keyword+'，记录平凡里的光'],
      '种草':['被 '+keyword+' 狠狠种草了！','入手 '+keyword+' 后真香',''+keyword+' 测评｜值不值得买'],
      '文艺':[keyword+'，是一首诗的开头','关于 '+keyword+' 的慢镜头','把 '+keyword+' 写成风的形状']},
    'xiaohongshu':{'日常':[''+keyword+'｜普通却安心','分享我的 '+keyword+' 小日常',''+keyword+' 也太好用了吧'],
      '种草':[''+keyword+' 保姆级攻略','闭眼入的 '+keyword+' 清单',''+keyword+' 使用心得（附图）'],
      '文艺':[''+keyword+' · 生活碎片','在 '+keyword+' 里遇见自己',''+keyword+'，温柔且有力量']},
    'twitter':{'日常':['Just logged '+keyword+' and it feels right.',''+keyword+' — small win today.','Hot take: '+keyword+' is underrated.'],
      '种草':['Why '+keyword+' is my new favorite.','Unpopular opinion: '+keyword+' >>> everything.',''+keyword+' thread 🧵'],
      '文艺':[''+keyword+', a quiet kind of magic.','On '+keyword+': the art of less.',''+keyword+' — poetry in motion.']}
  };
  var bank=(tpl[platform]&&tpl[platform][tone])?tpl[platform][tone]:['关于「'+keyword+'」的一点感想','今天想聊聊 '+keyword,'把 '+keyword+' 安利给同样喜欢的你'];
  var n=Math.min(4,bank.length), out=[], used={};
  while(out.length<n){ var i=Math.floor(rng()*bank.length); if(!used[i]){used[i]=1; out.push(bank[i]);} else if(Object.keys(used).length>=bank.length) break; }
  return {captions:out, platform:platform, tone:tone};
}
var EXPORTS={captionGen:captionGen};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CaptionForgePure = EXPORTS; }
